1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Step of {@code POST /api/owners} that assigns the owner's {@code customerCode}.
9	 *
10	 * <p>The code is formatted {@code '<LAST3>-<NNNN>'}, where LAST3 is the upper-cased first
11	 * three letters of the owner's last name and NNNN is a global 4-digit zero-padded sequence
12	 * equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}). Runs before
13	 * {@link SaveOwner}, so the count excludes the owner being created.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String lastName = owner.getLastName();
19	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
20	        int sequence = ownerRepository.findAll().size() + 1;
21	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
22	    }
23	}
