15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	            expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipNumber",
26	            expression = "java(owner.getCustomerCode() == null || owner.getRegistrationDate() == null ? null : owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
27	    @Mapping(target = "membershipTier",
28	            expression = "java(owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 && owner.getEmail() != null && !owner.getEmail().isBlank() ? \"SILVER\" : \"BRONZE\")")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    Owner toOwner(OwnerDto ownerDto);
32	
33	    @Mapping(target = "id", ignore = true)
34	    @Mapping(target = "pets", ignore = true)
35	    @Mapping(target = "customerCode", ignore = true)
36	    @Mapping(target = "householdId", ignore = true)
37	    @Mapping(target = "namesakeCount", ignore = true)
38	    Owner toOwner(OwnerFieldsDto ownerDto);
39	
40	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
41	
42	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
43	
44	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
45	        OwnerPageDto ownerPageDto = new OwnerPageDto();
46	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
47	        ownerPageDto.setPage(ownerPage.getNumber());
48	        ownerPageDto.setSize(ownerPage.getSize());
49	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
50	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
51	        return ownerPageDto;
52	    }
53	}
